template.script:
// 
    document.addEventListener('DOMContentLoaded', function() {
        // Handle delete item
        document.querySelectorAll('.delete-item').forEach(function(btn) {
            btn.addEventListener('click', function() {
                const lineId = this.getAttribute('data-line-id');
                updateCart(lineId, 0);
            });
        });

        // Handle decrease quantity
        document.querySelectorAll('.decrease-qty').forEach(function(btn) {
            btn.addEventListener('click', function() {
                const lineId = this.getAttribute('data-line-id');
                const currentQty = parseFloat(this.getAttribute('data-qty'));
                const newQty = currentQty - 1;
                if (newQty >= 0) {
                    updateCart(lineId, newQty);
                }
            });
        });

        // Handle increase quantity
        document.querySelectorAll('.increase-qty').forEach(function(btn) {
            btn.addEventListener('click', function() {
                const lineId = this.getAttribute('data-line-id');
                const currentQty = parseFloat(this.getAttribute('data-qty'));
                const newQty = currentQty + 1;
                updateCart(lineId, newQty);
            });
        });

        function updateCart(lineId, qty) {
            // Make AJAX call to update cart
            fetch('/shop/cart/update_line', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    jsonrpc: '2.0',
                    method: 'call',
                    params: {
                        line_id: lineId,
                        set_qty: qty
                    }
                })
            })
            .then(response => response.json())
            .then(data => {
                if (data.result && data.result.success) {
                    // If item was deleted (qty = 0), remove the card
                    if (qty === 0) {
                        const card = document.querySelector('.delete-item[data-line-id="' + lineId + '"]').closest('.card');
                        card.style.transition = 'opacity 0.3s';
                        card.style.opacity = '0';
                        setTimeout(function() {
                            card.remove();
                            // Check if cart is empty
                            if (data.result.line_count === 0) {
                                location.reload();
                            }
                        }, 300);
                    } else {
                        // Update quantity display
                        const qtyDisplay = document.querySelector('.qty-display[data-line-id="' + lineId + '"]');
                        if (qtyDisplay) {
                            qtyDisplay.textContent = Math.floor(qty);
                        }
                        // Update data-qty attributes
                        document.querySelectorAll('[data-line-id="' + lineId + '"]').forEach(function(el) {
                            if (el.hasAttribute('data-qty')) {
                                el.setAttribute('data-qty', qty);
                            }
                        });
                    }

                    // Update order summary
                    updateOrderSummary(data.result);
                }
            })
            .catch(error => {
                console.error('Cart update error:', error);
            });
        }

        function updateOrderSummary(cartData) {
            // Update subtotal
            const subtotalEl = document.querySelector('.d-flex.justify-content-between.mb-3 span:last-child');
            if (subtotalEl) {
                subtotalEl.textContent = cartData.currency_symbol + ' ' + cartData.amount_untaxed.toFixed(2);
            }

            // Update total
            const totalEl = document.querySelector('.d-flex.justify-content-between.mb-4 span.font-weight-700.font-size-1\\.5rem');
            if (totalEl) {
                totalEl.textContent = cartData.currency_symbol + ' ' + cartData.amount_total.toFixed(2);
            }
        }
    });
//
